def dot(u, v):
    return sum(x * y for x, y in zip(u, v))

a, b = [4, 3], [5, 2]
scale = dot(a, b) / dot(b, b)
print(round(scale, 3))  # 0.897

def dot(u, v):
    return sum(x * y for x, y in zip(u, v))

a, b = [4, 3], [5, 2]
scale = dot(a, b) / dot(b, b)
proj = [scale * x for x in b]
print([round(x, 2) for x in proj])  # [4.48, 1.79]
